module.exports = {
  evaluate: function(expr) {
    // Remove spaces
    expr = expr.replace(/\s+/g, '');

    // Helper function to parse numbers
    function parseNumber(expr) {
      const match = expr.match(/^\d+(\.\d+)?/);
      if (match) {
        return { value: parseFloat(match[0]), rest: expr.slice(match[0].length) };
      }
      throw new Error('Invalid number');
    }

    // Helper function to parse expressions
    function parseExpression(expr) {
      let { value, rest } = parseNumber(expr);

      while (rest.length > 0) {
        const op = rest[0];
        rest = rest.slice(1);

        if (op === '+' || op === '-' || op === '*' || op === '/') {
          const { value: nextValue, rest: nextRest } = parseNumber(rest);
          switch (op) {
            case '+':
              value += nextValue;
              break;
            case '-':
              value -= nextValue;
              break;
            case '*':
              value *= nextValue;
              break;
            case '/':
              if (nextValue === 0) {
                throw new Error('Division by zero');
              }
              value /= nextValue;
              break;
          }
          rest = nextRest;
        } else {
          throw new Error('Invalid operator');
        }
      }

      return value;
    }

    return parseExpression(expr);
  }
};

