def status_counts(entries):
    counts = {}
    for entry in entries:
        status = entry.split()[1]
        if status in counts:
            counts[status] += 1
        else:
            counts[status] = 1
    return counts

def error_rate(entries):
    if not entries:
        return 0.0
    error_count = sum(1 for entry in entries if int(entry.split()[1]) >= 500)
    return round(error_count / len(entries), 4)

