class Graph:
    def __init__(self):
        self.nodes = set()
        self.edges = {}
        self.visited = {}
        self.rec_stack = set()

    def add_node(self, n):
        self.nodes.add(n)

    def add_edge(self, a, b, weight=1):
        if a in self.nodes and b in self.nodes:
            self.edges[(a, b)] = weight
            self.nodes.add(b)
            self.nodes.add(a)

    def nodes(self):
        return list(self.nodes)

    def neighbors(self, a):
        return self.edges.get(a, [])

    def bfs(self, start):
        visited = set()
        queue = [start]
        while queue:
            node = queue.pop(0)
            if node not in visited:
                visited.add(node)
                queue.extend(self.neighbors(node))
        return visited

    def shortest_path(self, a, b):
        if a not in self.nodes or b not in self.nodes:
            raise KeyError("Unknown node")

        if a == b:
            return (0, [a])

        import heapq
        priority_queue = [(0, [a])]
        visited = set()

        while priority_queue:
            cost, path = heapq.heappop(priority_queue)
            node = path[-1]

            if node in visited:
                continue

            visited.add(node)

            if node == b:
                return (cost, path)

            for neighbor in self.neighbors(node):
                if neighbor not in visited:
                    new_cost = cost + self.edges.get((node, neighbor), float('inf'))
                    new_path = path + [neighbor]
                    heapq.heappush(priority_queue, (new_cost, new_path))

        return None

    def has_cycle(self):
        visited = set()
        rec_stack = set()

        def dfs(node):
            visited.add(node)
            rec_stack.add(node)

            for neighbor in self.neighbors(node):
                if neighbor not in visited:
                    if dfs(neighbor):
                        return True
                elif neighbor in rec_stack:
                    return True

            rec_stack.remove(node)
            return False

        for node in self.nodes:
            if node not in visited:
                if dfs(node):
                    return True
        return False

    def topo_order(self):
        visited = set()
        order = []

        def dfs(node):
            visited.add(node)
            for neighbor in self.neighbors(node):
                if neighbor not in visited:
                    dfs(neighbor)
            order.append(node)

        for node in self.nodes:
            if node not in visited:
                dfs(node)

        return order[::-1]

class Cache {
  peek(key) {
    const entry = this.cache.get(key);
    if (entry && (!entry.expiry || entry.expiry > this.now())) {
      return entry.value;
    }
    return undefined;
  }
  constructor(capacity, options = {}) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new Error("Capacity must be a positive integer");
    }
    this.capacity = capacity;
    this.cache = new Map();
    this.usageOrder = [];
    this.ttl = options.ttl || null;
    this.now = options.now || Date.now;
  }
  set(key, value, options = {}) {
    const expiry = options.ttl !== undefined ? this.now() + options.ttl : this.ttl;
    const entry = { value, expiry };
    if (this.cache.has(key)) {
      this.cache.delete(key);
      this.usageOrder.splice(this.usageOrder.indexOf(key), 1);
    } else if (this.cache.size >= this.capacity) {
      const lruKey = this.usageOrder.shift();
      this.cache.delete(lruKey);
    }
    this.cache.set(key, entry);
    this.usageOrder.push(key);
  }
  get(key) {
    const entry = this.cache.get(key);
    if (entry && (!entry.expiry || entry.expiry > this.now())) {
      this.usageOrder.splice(this.usageOrder.indexOf(key), 1);
      this.usageOrder.push(key);
      return entry.value;
    }
    return undefined;
  }
  has(key) {
    const entry = this.cache.get(key);
    return entry && (!entry.expiry || entry.expiry > this.now());
  }
  size() {
    return this.cache.size;
  }
  delete(key) {
    if (this.cache.has(key)) {
      this.cache.delete(key);
      this.usageOrder.splice(this.usageOrder.indexOf(key), 1);
      return true;
    }
    return false;
  }
  clear() {
    this.cache.clear();
    this.usageOrder.length = 0;
  }
}
